import { quoteBooking } from "./quote_booking";

const categories = ["standard", "suite", "villa", "penthouse", undefined];
const loyaltys = [-1, 0, 1, 2, 3, 4, 2.5, "3", undefined];
const nightss = [0, 1, 2, 3, 14, 15, 21, 22, 28, 29, 2.5, "3", undefined];
const guestss = [0, 1, 2, 3, 4, 5, 8, 9, 2.5, "4", undefined];
const seasons = ["low", "high", "peak", undefined];
const coupons = ["VIP", "GOLD", undefined, 5];

let count = 0, mismatch = 0;
for (const category of categories)
for (const loyaltyYears of loyaltys)
for (const nights of nightss)
for (const guests of guestss)
for (const season of seasons)
for (const coupon of coupons) {
  const raw: any = {};
  if (category !== undefined) raw.category = category;
  if (loyaltyYears !== undefined) raw.loyaltyYears = loyaltyYears;
  if (nights !== undefined) raw.nights = nights;
  if (guests !== undefined) raw.guests = guests;
  if (season !== undefined) raw.season = season;
  if (coupon !== undefined) raw.coupon = coupon;
  count++;
  try {
    quoteBooking(raw);
  } catch (e) {
    console.log("THREW", e, JSON.stringify(raw));
    mismatch++;
  }
}
console.log("count", count, "mismatch", mismatch);
