    return { ok: false, error: "unknown category" };
  }

  const nights = isInteger(req.nights) ? req.nights : undefined;
  if (nights === undefined || nights < spec.minNights || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }

  if (spec.minStay !== undefined && nights < spec.minStay) {
    return { ok: false, error: `${spec.label} minimum stay` };
  }

  const guests = isInteger(req.guests) ? req.guests : undefined;
  if (guests === undefined || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const isHigh = req.season === "high";

  // A VIP coupon or 3+ years of loyalty earns the 10% discount and a flexible policy.
  const premium = req.coupon === "VIP" || loyaltyYears >= 3;

  let total = spec.baseRate * nights;
  if (isHigh) {
    total += spec.highSurcharge * nights;
  }
  if (premium) {
    total -= Math.floor(total / 10);
  }
  if (
    spec.extraGuestFee !== undefined &&
    spec.extraGuestThreshold !== undefined &&
    guests > spec.extraGuestThreshold
  ) {
    total += spec.extraGuestFee;
  }
  if (spec.flatFee !== undefined) {
    total += spec.flatFee;
  }

  const policy = premium ? "flex" : "strict";
  const line = `${spec.label}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

